function Apply-ProfileNvidReliabilityOverrides {
function global:Get-NvidOfficialDriverInfo {

    [CmdletBinding()]
    param([string]$GpuName)

    $gpuText = [string]$GpuName
    if ([string]::IsNullOrWhiteSpace($gpuText)) {
        $gpuText = [string](Get-CimInstance Win32_VideoController -ErrorAction Stop | Where-Object { $_.Name -match 'NVIDIA' } | Select-Object -First 1 -ExpandProperty Name)
    }
    if ([string]::IsNullOrWhiteSpace($gpuText)) {
        throw 'No NVIDIA adapter was detected for official driver lookup.'
    }

    $pfid = switch -Regex ($gpuText) {
        '5090' { '1066'; break }
        '5080' { '1065'; break }
        '5070\s*Ti' { '1068'; break }
        '5070' { '1070'; break }
        default { $null }
    }
    if (-not $pfid) {
        throw ("Unsupported NVIDIA adapter for automatic driver lookup: {0}" -f $gpuText)
    }

    $lookupUrl = ('https://gfwsl.geforce.com/services_toolkit/services/com/nvidia/services/AjaxDriverService.php?func=DriverManualLookup&dch=1&osID=57&pfid={0}&numberOfResults=20&languageCode=1033&isWHQL=1&dltype=1' -f $pfid)
    $lookupError = $null
    try {
        $response = Invoke-RestMethod -Uri $lookupUrl -UseBasicParsing -TimeoutSec 20 -ErrorAction Stop
        $items = @($response.IDS | ForEach-Object { $_.downloadInfo } | Where-Object { $_.Success -eq '1' -and $_.DownloadURL })
        $candidates = foreach ($item in $items) {
            $versionText = [System.Uri]::UnescapeDataString([string]$item.Version)
            try { $version = [Version]$versionText } catch { continue }
            [pscustomobject]@{ Item = $item; VersionText = $versionText; Version = $version }
        }
        $selected = $candidates | Sort-Object Version -Descending | Select-Object -First 1
        if ($selected) {
            $item = $selected.Item
            $products = foreach ($series in @($item.series)) {
                foreach ($product in @($series.products)) {
                    if ($product.productName) { [System.Uri]::UnescapeDataString([string]$product.productName) }
                }
            }
            return [pscustomobject]@{
                Version           = $selected.VersionText
                ReleaseDate       = [System.Uri]::UnescapeDataString([string]$item.ReleaseDateTime)
                DownloadURL       = [System.Uri]::UnescapeDataString([string]$item.DownloadURL)
                DetailsURL        = [System.Uri]::UnescapeDataString([string]$item.DetailsURL)
                FileSize          = [System.Uri]::UnescapeDataString([string]$item.DownloadURLFileSize)
                Name              = [System.Uri]::UnescapeDataString([string]$item.Name)
                SupportedProducts = @($products | Select-Object -Unique)
                SourceURL         = $lookupUrl
                LookupGpuName     = $gpuText
                LookupPfID        = $pfid
            }
        }
        $lookupError = 'NVIDIA returned no installable driver entries.'
    } catch {
        $lookupError = $_.Exception.Message
    }

    $smi = @('C:\Windows\System32\nvidia-smi.exe', 'C:\Program Files\NVIDIA Corporation\NVSMI\nvidia-smi.exe') | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } | Select-Object -First 1
    if ($smi) {
        $installedVersion = ([string](& $smi --query-gpu=driver_version --format=csv,noheader 2>$null | Select-Object -First 1)).Trim()
        if ($installedVersion) {
            return [pscustomobject]@{
                Version           = $installedVersion
                ReleaseDate       = 'installed-fallback-after-official-lookup-error'
                DownloadURL       = ''
                DetailsURL        = ''
                FileSize          = ''
                Name              = 'Installed NVIDIA Driver'
                SupportedProducts = @($gpuText)
                SourceURL         = $lookupUrl
                LookupGpuName     = $gpuText
                LookupPfID        = $pfid
                LookupError       = $lookupError
            }
        }
    }
    throw ("Unable to determine a compatible NVIDIA driver for '{0}': {1}" -f $gpuText, $lookupError)

}

    function global:Get-NvidOfficialAppInfo {
        $pageUrl = 'https://www.nvidia.com/en-us/software/nvidia-app/'
        $releaseUrl = 'https://www.nvidia.com/en-us/software/nvidia-app/release-highlights/'
        $known = [pscustomobject]@{ Version = '11.0.7.247'; DownloadURL = 'https://us.download.nvidia.com/nvapp/client/11.0.7.247/NVIDIA_app_v11.0.7.247.exe'; PageURL = $pageUrl; ReleaseURL = $releaseUrl; Source = 'pinned-official-fallback-after-nvidia-page-error' }
        $headers = @{ 'User-Agent' = 'Mozilla/5.0 WindowsPowerShell/5.1 nvid'; 'Cache-Control' = 'no-cache'; 'Pragma' = 'no-cache' }
        for ($attempt = 1; $attempt -le 4; $attempt++) {
            try {
                $response = Invoke-WebRequest -Uri $pageUrl -UseBasicParsing -TimeoutSec 45 -Headers $headers
                $matches = [regex]::Matches([string]$response.Content, 'https://(?:us\.)?download\.nvidia\.com/nvapp/client/(?<version>[\d\.]+)/NVIDIA_app_v(?<fileversion>[\d\.]+)\.exe')
                $candidates = @()
                foreach ($m in $matches) {
                    if ($m.Groups['fileversion'].Success -and $m.Value) {
                        $candidates += [pscustomobject]@{ Version = [string]$m.Groups['fileversion'].Value; DownloadURL = [string]$m.Value; PageURL = $pageUrl; ReleaseURL = $releaseUrl; Source = 'nvidia-software-page' }
                    }
                }
                $best = $candidates | Sort-Object @{ Expression = { try { [version]$_.Version } catch { [version]'0.0' } } } -Descending | Select-Object -First 1
                if ($best) { return $best }
            } catch {
                Write-Host ("  NVIDIA App official page lookup attempt {0}/4 failed: {1}" -f $attempt,$_.Exception.Message) -ForegroundColor DarkYellow
                Start-Sleep -Seconds ([Math]::Min(12, 2 * $attempt))
            }
        }
        try {
            $statusPath = 'C:\ProgramData\NVIDIA Corporation\NVIDIA App\UpdateFramework\status\nvapp\updatecheck.json'
            if (Test-Path -LiteralPath $statusPath) {
                $status = Get-Content -LiteralPath $statusPath -Raw | ConvertFrom-Json
                foreach ($item in @($status)) {
                    if ($item.updateInfoJSON) {
                        $info = $item.updateInfoJSON | ConvertFrom-Json
                        if ($info.version -and $info.url) { return [pscustomobject]@{ Version = [string]$info.version; DownloadURL = [string]$info.url; PageURL = $pageUrl; ReleaseURL = $releaseUrl; Source = 'local-nvidia-update-status' } }
                    }
                }
            }
        } catch {}
        return $known
    }

    function global:Get-NvidOfficialPhysXInfo {
        $pageUrl = 'https://www.nvidia.com/en-us/drivers/physx-system-software/'
        $headers = @{ 'User-Agent' = 'Mozilla/5.0 WindowsPowerShell/5.1 nvid'; 'Cache-Control' = 'no-cache'; 'Pragma' = 'no-cache' }
        for ($attempt = 1; $attempt -le 4; $attempt++) {
            try {
                $response = Invoke-WebRequest -Uri $pageUrl -UseBasicParsing -TimeoutSec 45 -Headers $headers
                $match = [regex]::Match([string]$response.Content, '/Windows/(?<version>[\d\.]+)/PhysX_(?<fileversion>[\d\.]+)_SystemSoftware\.exe')
                if ($match.Success) {
                    $version = $match.Groups['fileversion'].Value
                    return [pscustomobject]@{ Version = $version; DownloadURL = ('https://us.download.nvidia.com/Windows/{0}/PhysX_{0}_SystemSoftware.exe' -f $version); PageURL = $pageUrl; Source = 'nvidia-physx-page' }
                }
            } catch {
                Write-Host ("  PhysX official page lookup attempt {0}/4 failed: {1}" -f $attempt,$_.Exception.Message) -ForegroundColor DarkYellow
                Start-Sleep -Seconds ([Math]::Min(12, 2 * $attempt))
            }
        }
        return [pscustomobject]@{ Version = '9.23.1019'; DownloadURL = 'https://us.download.nvidia.com/Windows/9.23.1019/PhysX_9.23.1019_SystemSoftware.exe'; PageURL = $pageUrl; Source = 'pinned-official-fallback-after-nvidia-page-error' }
    }

    function global:Open-NvidStartApp {
        param(
            [string]$AppId,
            [string[]]$TitlePattern,
            [string[]]$ProcessNames = @(),
            [string[]]$ExcludeTitlePattern = @(),
            [int]$TimeoutSeconds = 90
        )
        if ([string]::IsNullOrWhiteSpace($AppId)) { throw 'AppId is required to launch the NVIDIA surface.' }
        $titleText = ($TitlePattern -join ', ')
        $window = Wait-NvidWindow -TitlePattern $TitlePattern -ProcessNames $ProcessNames -ExcludeTitlePattern $ExcludeTitlePattern -TimeoutSeconds 4
        if ($window) { return $window }
        Start-Process -FilePath 'explorer.exe' -ArgumentList ("shell:AppsFolder\" + $AppId) | Out-Null
        $window = Wait-NvidWindow -TitlePattern $TitlePattern -ProcessNames $ProcessNames -ExcludeTitlePattern $ExcludeTitlePattern -TimeoutSeconds $TimeoutSeconds
        if ($window) { return $window }
        throw ("Timed out waiting for window '{0}' after launching '{1}'." -f $titleText, $AppId)
    }
